// ── O QUE AJUSTAR AQUI ───────────────────────────────────────────
// Nada, no caso normal. O no anterior perguntou ao Chatwoot QUANTAS
// conversas existem no total, e daqui saem todas as paginas ate cobrir
// esse numero — janeiro incluido. Foi o erro da primeira versao: ela
// varria 20 paginas fixas (500 conversas) e, como o Chatwoot devolve da
// mais recente para a mais antiga, so trazia os ultimos dez dias.
//
// COMO RODAR (duas passadas, e de proposito):
//
//   1a) Assim como esta. So a lista de conversas: 132 chamadas para 3.286
//       conversas, um minuto, e o WhatsLive ja mostra todo mundo desde
//       janeiro com a ultima fala de cada um.
//
//   2a) Depois, para trazer as mensagens: TRAZER_MENSAGENS = true e
//       PAGINAS_MAX = 20, rodando com PAGINA_INICIAL 1, 21, 41... ate o
//       Placar dizer que a ultima pagina passou. Aqui e UMA chamada por
//       conversa — 3.286 delas de uma vez estoura o tempo da execucao.
const TRAZER_MENSAGENS = false;
const PAGINA_INICIAL = 1;
const PAGINAS_MAX = 0;

const POR_PAGINA = 25;   // o Chatwoot nao deixa passar disso
const TETO = 600;        // trava de seguranca: 15.000 conversas

const r = $json || {};
const meta = (r.data && r.data.meta) || r.meta || {};
const total = Number(meta.all_count || 0);
if (!total) {
  throw new Error('O Chatwoot nao informou o total de conversas (meta.all_count). '
    + 'Confira a credencial e se a conta e mesmo a de id 1.');
}

const ultimaPagina = Math.min(Math.ceil(total / POR_PAGINA), TETO);
const fim = PAGINAS_MAX > 0
  ? Math.min(PAGINA_INICIAL + PAGINAS_MAX - 1, ultimaPagina)
  : ultimaPagina;

const paginas = [];
for (let p = PAGINA_INICIAL; p <= fim; p++) {
  paginas.push({ json: { pagina: p, trazerMensagens: TRAZER_MENSAGENS, total, ultimaPagina } });
}
if (!paginas.length) {
  throw new Error('PAGINA_INICIAL (' + PAGINA_INICIAL + ') passou da ultima pagina (' + ultimaPagina + ').');
}
return paginas;

// Cada conversa do Chatwoot vira um registro no formato que o Inbox ja
// desenha — o MESMO de sempre, para historico e mensagem nova ficarem
// indistinguiveis na tela.
//
// Nao filtra por caixa de proposito: assim o numero novo e o antigo
// entram na mesma varredura, que e o que se quer ao trazer o historico.
const caixas = {};
try {
  const lc = $('Listar caixas').first().json;
  (lc.payload || lc.data || []).forEach(i => { caixas[i.id] = i.name || ''; });
} catch (e) { /* sem os nomes, o Inbox so nao mostra o selo da caixa */ }

const saida = [];
for (const item of $input.all()) {
  const r = item.json || {};
  const lista = (r.data && r.data.payload) || r.payload || [];
  for (const c of lista) {
    const num = c.id;                    // display_id da conversa
    if (!num) continue;
    const contato = (c.meta && c.meta.sender) || {};
    const ultima = c.last_non_activity_message || {};
    const mtU = ultima.message_type;
    const deU = ultima.private === true ? 'nota'
              : (mtU === 1 || mtU === 3 || mtU === 'outgoing' || mtU === 'template') ? 'agente'
              : 'cliente';
    let ts = (c.timestamp || c.last_activity_at || ultima.created_at || 0);
    if (ts && ts < 1e12) ts = ts * 1000;
    let texto = String(ultima.content || '').trim();
    if (!texto && Array.isArray(ultima.attachments) && ultima.attachments.length) {
      const tipos = { image: 'imagem', audio: 'audio', video: 'video', file: 'arquivo' };
      texto = '[' + (tipos[ultima.attachments[0].file_type] || 'anexo') + ']';
    }
    saida.push({ json: {
      convId: 'cw_' + num,
      convNum: num,
      trazerMensagens: item.json.trazerMensagens !== false,
      conv: {
        id: 'cw_' + num,
        nome: contato.name || 'Contato',
        telefone: String(contato.phone_number || '').trim(),
        caixa: caixas[c.inbox_id] || '',
        ultima: texto.slice(0, 120),
        deUltima: deU,
        ts: ts || Date.now(),
      },
    } });
  }
}
return saida;

// As conversas sobem em blocos de 200 numa chamada so — uma por uma
// seriam milhares de chamadas e a varredura levaria horas.
const BLOCO = 200;
const todas = $input.all().map(i => i.json.conv).filter(c => c && c.id);
const saida = [];
for (let i = 0; i < todas.length; i += BLOCO) {
  const mapa = {};
  todas.slice(i, i + BLOCO).forEach(c => { mapa[c.id] = c; });
  saida.push({ json: { corpo: mapa, quantas: Object.keys(mapa).length } });
}
return saida.length ? saida : [{ json: { corpo: {}, quantas: 0 } }];

// Sem mensagens pedidas, a varredura para aqui: as conversas ja foram
// gravadas e o Inbox ja mostra todo mundo com a ultima fala.
return $input.all().filter(i => i.json.trazerMensagens);

// Mesma classificacao do fluxo ao vivo — cliente, agente e a NOTA
// interna (o cadeado), que e como o envio de template pelo Gupshup fica
// registrado. Historico e mensagem nova precisam ficar iguais na tela.
const saida = [];
const entradas = $input.all();
for (let i = 0; i < entradas.length; i++) {
  const r = entradas[i].json || {};
  const lista = r.payload || (r.data && r.data.payload) || [];
  let convId = '';
  try { convId = $('So quem quer mensagens').all()[i].json.convId; } catch (e) {}
  if (!convId || !lista.length) continue;

  const mapa = {};
  for (const m of lista) {
    const mt = m.message_type;
    const deCliente = mt === 0 || mt === 'incoming';
    const ehTemplate = mt === 3 || mt === 'template';
    const deAgente = mt === 1 || mt === 'outgoing' || ehTemplate;
    if (!deCliente && !deAgente) continue;          // atividade do sistema
    const privada = m.private === true;

    let texto = String(m.content || '').trim();
    const anexos = Array.isArray(m.attachments) ? m.attachments : [];
    if (!texto && anexos.length) {
      const tipos = { image: 'imagem', audio: 'audio', video: 'video', file: 'arquivo' };
      texto = '[' + (tipos[anexos[0].file_type] || 'anexo') + ']';
    }
    if (!texto) continue;
    // O eco da persona e os comandos internos nao viram balao
    if (deAgente && !privada && texto.indexOf('*Manoel - Suplelive:*') === 0) continue;
    if (deAgente && !privada && texto[0] === '/') continue;

    let ts = m.created_at || 0;
    if (ts && ts < 1e12) ts = ts * 1000;
    const quem = (((m.sender && m.sender.name) || '?').trim().split(/\s+/)[0]);
    mapa['m' + m.id] = {
      texto: texto.slice(0, 4000),
      de: privada ? 'nota' : (deAgente ? 'agente' : 'cliente'),
      autor: privada ? quem : (deAgente ? ('Manoel (' + quem + ')') : ''),
      ts: ts || Date.now(),
    };
  }
  if (Object.keys(mapa).length) saida.push({ json: { convId, corpo: mapa, quantas: Object.keys(mapa).length } });
}
return saida;

// O placar da varredura. Agora ele sabe o tamanho do alvo, entao da para
// conferir de olho se veio tudo — e nao ficar adivinhando se falta pagina.
let conversas = 0, mensagens = 0, falhas = 0, total = 0, paginas = 0;
try {
  const p = $('Paginas a varrer').all();
  paginas = p.length;
  total = Number(p[0].json.total || 0);
} catch (e) {}
try { $('Agrupar conversas').all().forEach(i => { conversas += (i.json.quantas || 0); }); } catch (e) {}
try { $('Converter mensagens').all().forEach(i => { mensagens += (i.json.quantas || 0); }); } catch (e) {}
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.ok === false || j.erro) falhas++;
}

const faltou = total && conversas < total - 5;   // margem: conversas criadas durante a varredura
return [{ json: {
  totalNoChatwoot: total,
  paginasVarridas: paginas,
  conversas,
  mensagens,
  falhas,
  recado: !conversas
    ? 'Nenhuma conversa voltou — confira a credencial do Chatwoot.'
    : (faltou
      ? ('Vieram ' + conversas + ' de ' + total + ' conversas. Faltou gente: rode de novo, '
         + 'ou quebre em blocos com PAGINA_INICIAL / PAGINAS_MAX no no "Paginas a varrer".')
      : ('Varredura completa: ' + conversas + ' conversa(s) de ' + total + ' e '
         + mensagens + ' mensagem(ns). Nao precisa rodar de novo.')),
} }];
